  "✅ Τι να κάνεις αυτή την εβδομάδα": "✅ What to do this week",
  "Τίποτα επείγον. 👌 Κράτα τις ενημερώσεις και ξανακοίτα την επόμενη εβδομάδα.": "Nothing urgent. 👌 Keep up with updates and check again next week.",
