  "📟 Νέες συσκευές": "📟 New devices",
  "Πρώτη φορά": "First seen",
  "Αν κάποια δεν την αναγνωρίζεις, άλλαξε τον κωδικό του Wi‑Fi.": "If you don't recognise one, change your Wi‑Fi password.",
  "🔌 IoT συσκευές": "🔌 IoT devices",
