  "Το `ss` είναι του Linux. Στο Mac: `netstat -an` ή `lsof -i -nP`.": "`ss` is a Linux command. On a Mac: `netstat -an` or `lsof -i -nP`.",
  "Το `apt` εγκαθιστά πακέτα στο Raspberry Pi/Debian. Στο Mac το αντίστοιχο είναι το `brew install …` (από δικό σου Terminal).": "`apt` installs packages on Raspberry Pi/Debian. On a Mac the equivalent is `brew install …` (from your own Terminal).",
