  "δεν είναι εγκατεστημένο σε αυτόν τον υπολογιστή (": "isn't installed on this computer (",
  "RDP: απομακρυσμένη επιφάνεια εργασίας, κύρια πόρτα εισόδου για ransomware · Self-signed πιστοποιητικό — ο browser δεν μπορεί να ελέγξει ότι μιλάς με τη σωστή συσκευή (κίνδυνος MITM)": "RDP: remote desktop, a main way in for ransomware · Self-signed certificate — the browser can't check that you're talking to the right device (MITM risk)",
  "Κλείσε τις υπηρεσίες Κοινής χρήσης που δεν χρειάζεσαι · Ρυθμίσεις → Γενικά → AirDrop και Handoff → Δέκτης AirPlay: off": "Turn off the Sharing services you don't need · Settings → General → AirDrop & Handoff → AirPlay Receiver: off",
  "Κλείσε τις υπηρεσίες Κοινής χρήσης που δεν χρειάζεσαι · Ρυθμίσεις → Γενικά → Κοινή χρήση → Απομακρυσμένη διαχείριση: off": "Turn off the Sharing services you don't need · Settings → General → Sharing → Remote Management: off",
  "Κλείσε τις υπηρεσίες Κοινής χρήσης που δεν χρειάζεσαι · Ρυθμίσεις → Γενικά → Κοινή χρήση → Απομακρυσμένη σύνδεση: off": "Turn off the Sharing services you don't need · Settings → General → Sharing → Remote Login: off",
  "Κλείσε τις υπηρεσίες Κοινής χρήσης που δεν χρειάζεσαι · Ρυθμίσεις → Γενικά → Κοινή χρήση → Κοινή χρήση αρχείων: off": "Turn off the Sharing services you don't need · Settings → General → Sharing → File Sharing: off",
  "Κλείσε τις υπηρεσίες Κοινής χρήσης που δεν χρειάζεσαι · Ρυθμίσεις → Γενικά → Κοινή χρήση → Κοινή χρήση εκτυπωτή: off": "Turn off the Sharing services you don't need · Settings → General → Sharing → Printer Sharing: off",
