  "Το όνομα υπάρχει μόνο στο τοπικό δίκτυο (π.χ. router.home) — φυσιολογικό.": "The name only exists on the local network (e.g. router.home) — that's normal.",
  "Ο Σύστημα λέει ότι το όνομα δεν υπάρχει, ενώ οι δημόσιοι το βρίσκουν — φίλτρο (Pi-hole, γονικός έλεγχος) ή παραποίηση DNS.": "The system resolver says the name doesn't exist, while the public resolvers find it — a filter (Pi-hole, parental control) or DNS tampering.",
  "Ο Σύστημα δίνει εντελώς διαφορετικές IP — συνήθως CDN (άλλος server ανά περιοχή), όχι απαραίτητα πρόβλημα.": "The system resolver returns completely different IPs — usually a CDN (a different server per region), not necessarily a problem.",
  "Ο Router λέει ότι το όνομα δεν υπάρχει, ενώ οι δημόσιοι το βρίσκουν — φίλτρο (Pi-hole, γονικός έλεγχος) ή παραποίηση DNS.": "The router says the name doesn't exist, while the public resolvers find it — a filter (Pi-hole, parental control) or DNS tampering.",
